		class LabelWithErrorHandling : CargoWise.Windows.UI.KLabel
		{
			protected override void OnPaint(PaintEventArgs e)
			{
				try
				{
					base.OnPaint(e);
				}
				catch (OutOfMemoryException) //GDI+ generic error
				{
					this.Image = null;
					try
					{
						base.OnPaint(e);
					}
					catch (Exception ex) when (!ex.IsCriticalException())
					{
					}
				}
			}
		}

		#region Image

		protected Image AWBImage
		{
			get
			{
				if (fAWBImage == null)
				{
					using (var image = Image.FromStream(typeof(AWBUserControl).Assembly.GetManifestResourceStream("Enterprise.Freight.Forwarding.GUI.AWB.AWBBackgroundImage.png")))
					{
						fAWBImage = new Bitmap(image, CargoWise.Windows.UI.ControlDpiScalingHelper.NewScaledSize(image.Width, image.Height));
					}
				}

				return fAWBImage;
			}
		}
		Image fAWBImage;

		#endregion

		#region Binding

		protected override void OnCurrentDataItemChanging(EventArgs e)
		{
			base.OnCurrentDataItemChanging(e);
			exportAWB = null;
		}

		protected override void OnCurrentDataItemChanged(EventArgs e)
		{
			base.OnCurrentDataItemChanged(e);
			IAWBParent awbParent = CurrentDataItem as IAWBParent;
			if (CurrentDataItem != null && awbParent == null)
			{
				throw new NotImplementedException("IAWBParent needs to be implemented for this form to work");
			}
			exportAWB = awbParent == null ? null : awbParent.AWBHeader;
		}

		protected ExportAWBHeader exportAWB;

		public override void SetDataBinding(object dataSource, string dataMember)
		{
			base.SetDataBinding(dataSource, dataMember);
			if (dataSource != null)
			{
				SetAddressOverrideZTextBoxesFont();
				SetAddressOverrideTabsVisibility();
				EH_SecurityStatusTextBox.Visible = exportAWB?.SecurityStatusAWBVisibility ?? false;
				IsDeclarantForAdvanceCargoReportingCheckBox.Visible = exportAWB != null && exportAWB.IsMAWB ? exportAWB.HasInboundToICS2Zone : false;
			}
		}

		#endregion

		#region Font Calculations

		Font fFontForAddress;
		Font GetFontForAddress()
		{
			if (fFontForAddress == null)
			{
				fFontForAddress = new Font("Arial", 8);
			}
			return fFontForAddress;
		}

		protected bool IsThereSpaceForNextCharacter(string text, int maxFieldWidthInDB, int maxTextWidthInMillimeters)
		{
			if (text.Length <= 1)
			{
				return true;
			}

			IAWBParent awbParent = CurrentDataItem as IAWBParent;
			if (awbParent != null && awbParent.AWBHeader != null)
			{
				var lineBreaker = new Forwarding.AWB.Business.LineBreaker(maxFieldWidthInDB, maxFieldWidthInDB, maxTextWidthInMillimeters, Forwarding.AWB.Business.NatureAndQtyOfGoods.Font);
				return lineBreaker.IsThereSpaceForNextString(text);
			}
			else
			{
				return false;
			}
		}

		#endregion

