		protected void SetAddressOverrideZTextBoxesFont()
		{
			ZTextBox[] boxes = AddressOverrideBoxes();

			foreach (ZTextBox box in boxes)
			{
				box.Font = GetFontForAddress();
			}
		}

		bool IsInAddressOverrideTextChange;
		void AddressOverrideTextBox_TextChange(object sender, EventArgs e)
		{
			ZTextBox sender1 = (ZTextBox)sender;
			string fittingText = sender1.Text;
			if (!IsInAddressOverrideTextChange)
			{
				IsInAddressOverrideTextChange = true;
				const int MaxFieldWidthInDB = 150;
				const int MaxTextWidthInMillimeters = 107;
				int originalCaretPosition = sender1.SelectionStart;
				while (!IsThereSpaceForNextCharacter(fittingText, MaxFieldWidthInDB, MaxTextWidthInMillimeters))
				{
					fittingText = fittingText.Substring(0, fittingText.Length - 1);
				}
				sender1.Text = fittingText;
				sender1.SelectionStart = originalCaretPosition;
				IsInAddressOverrideTextChange = false;
			}
		}

