		#region Shipper Name TextBox

		bool IsShipperNameTextChage;

		void ShipperNameTextBox_TextChanged(object sender, EventArgs e)
		{
			ZTextBox sender1 = (ZTextBox)sender;
			string fittingText = sender1.Text;

			if (fittingText.Length > 15)
			{
				if (!IsShipperNameTextChage)
				{
					IsShipperNameTextChage = true;

					const int MaxTextWidthInMillimeters = 151;
					int originalCaretPosition = sender1.SelectionStart;
					while (!IsThereSpaceForNextCharacter(fittingText, ExportAWBHeaderSchema.EH_ShipperName.MaxLength, MaxTextWidthInMillimeters + 1))
					{
						fittingText = fittingText.Substring(0, fittingText.Length - 1);
					}
					sender1.Text = fittingText;
					sender1.SelectionStart = originalCaretPosition;
					IsShipperNameTextChage = false;
				}
			}
		}

		#endregion

		#region GetNewNatureAndQtyOfGoodsControl()

		protected virtual NatureAndQtyOfGoodsControl GetNewNatureAndQtyOfGoodsControl()
		{
			return new NatureAndQtyOfGoodsControl();
		}

		#endregion

		#region AWB Address

		void AWBAddressSaveButton_Click(object sender, EventArgs args)
		{
			if (!Env.Security.OrgAddressCapabilitiesModify.IsAllowed)
			{
				Globals.Message.ShowInformation(Res.GetString("e096a5df-2125-46fd-9c36-c6c4f23c7391", "You do not have the security right to modify addresses of an organization. Please check with your system administrator if you require access to this function."));

				return;
			}

			var organisationController = ZControllerFactory.Create(ControllerIDs.Organisation);

#if DEBUG
			LastOrganisationControllerForTesting = organisationController;
#endif

			OrgHeader orgHeaderForSaving = null;

			if (sender == ShipperAddressSaveButton)
			{
				orgHeaderForSaving = exportAWB.GetShipperOrgHeaderForSavingAWBAddress(organisationController.Factory);
			}
			else if (sender == ConsigneeAddressSaveButton)
			{
				orgHeaderForSaving = exportAWB.GetConsigneeOrgHeaderForSavingAWBAddress(organisationController.Factory);
			}
			else if (sender == AlsoNotifyAddressSaveButton)
			{
				orgHeaderForSaving = exportAWB.GetAlsoNotifyOrgHeaderForSavingAWBAddress(organisationController.Factory);
			}

			if (orgHeaderForSaving == null)
			{
				Globals.Message.ShowInformation(Res.GetString("90f0cec1-12f4-466b-8cff-e1da8698758b", "Cannot save this address as there is no real organization for this address."));

				return;
			}

			((IOrganisationController)organisationController).ShowForm(orgHeaderForSaving, OrganisationTabPages.Address, FormAction.Edit);
		}

#if DEBUG
		protected ZController LastOrganisationControllerForTesting { get; set; }
#endif

		#endregion

		#region Override AWB Checkbox

		void OverrideValuesCheckBox_Click(object sender, EventArgs args)
		{
			if (CurrentDataItem is IAWBParent awbParent
				&& !awbParent.IsOverrideAllowed)
			{
				Globals.Message.ShowError(
					Env.Security.GetErrorMessageForNotAllowed(
						awbParent.GetType() == typeof(ForwardingConsol)
							? Env.Security.MaintainConsolAWBOverride
							: Env.Security.MaintainShipmentAWBOverride));
			}
		}

		#endregion

		#region Implement

		protected override void Dispose(bool disposing)
		{
			if (disposing)
			{
				AWBImagelabel.Image = null;
				zLabel45.Image = null;

				if (fAWBImage != null)
				{
					fAWBImage.Dispose();
				}

				if (fFontForAddress != null)
				{
					fFontForAddress.Dispose();
				}

				UnhookEvents();
			}

			base.Dispose(disposing);
		}

		protected override void OnLoad(EventArgs e)
		{
			HookEvents();
			base.OnLoad(e);
		}

		#endregion

		#region Events

		void HookEvents()
		{
			this.ShipperAddressSaveButton.Click += AWBAddressSaveButton_Click;
			this.ConsigneeAddressSaveButton.Click += AWBAddressSaveButton_Click;
			this.AlsoNotifyAddressSaveButton.Click += AWBAddressSaveButton_Click;
		}

		void UnhookEvents()
		{
			this.ShipperAddressSaveButton.Click -= AWBAddressSaveButton_Click;
			this.ConsigneeAddressSaveButton.Click -= AWBAddressSaveButton_Click;
			this.AlsoNotifyAddressSaveButton.Click -= AWBAddressSaveButton_Click;
		}

		#endregion

		#region IAllowTabBackwardBetweenSomeOfMyChildren

		bool IAllowTabBackwardBetweenSomeOfMyChildren.AllowTabBackward(Control control, Control previousControl)
		{
			return control is ZTextBox && previousControl is ZTextBox;
		}

		#endregion
	}
